// Checks that every placeholder (paragraph or list-item text) is one italic span,
// apart from the bold glossary term in front of it, and prints the heading tree.
const cm = require("./node_modules/commonmark");
const fs = require("fs");
const doc = new cm.Parser().parse(fs.readFileSync(process.argv[2], "utf8"));
const text = n => { let t = "", w = n.walker(), e; while ((e = w.next())) if (e.entering && e.node.literal) t += e.node.literal; return t; };
let paras = 0, ok = 0, heads = [];
const w = doc.walker(); let e;
while ((e = w.next())) {
  const n = e.node; if (!e.entering) continue;
  if (n.type === "heading") heads.push("#".repeat(n.level) + " " + text(n));
  if (n.type === "paragraph") {
    paras++;
    const kids = []; let c = n.firstChild; while (c) { kids.push(c); c = c.next; }
    // Allowed shapes: [emph] or [strong, text(": "), emph]
    const plain = kids.length === 1 && kids[0].type === "emph";
    const glossary = kids.length === 3 && kids[0].type === "strong" && kids[1].type === "text" && kids[1].literal === ": " && kids[2].type === "emph";
    if (plain || glossary) ok++; else console.log("PROBLEM in paragraph", paras, ":", text(n).slice(0, 80));
  }
}
console.log("placeholders:", paras, "well-formed:", ok);
console.log(heads.join("\n"));
EOF
